import 'disease_result.dart';
import 'sensor_data.dart';
class CropState { final String variety,growthStage,plantingDate; final int daysAfterPlanting; CropState.fromJson(Map<String,dynamic> j):variety=j['variety']??'',growthStage=j['growthStage']??'',plantingDate=j['plantingDate']??'',daysAfterPlanting=(j['daysAfterPlanting']??0).toInt(); }
class RiskState { final double environmentalRisk,diseaseRisk,combinedRisk; final String riskLevel; RiskState.fromJson(Map<String,dynamic> j):environmentalRisk=(j['environmentalRisk']??0).toDouble(),diseaseRisk=(j['diseaseRisk']??0).toDouble(),combinedRisk=(j['combinedRisk']??0).toDouble(),riskLevel=j['riskLevel']??'Low'; }
class PredictionState { final double current,after1Hour,after3Hours,after6Hours; final bool irrigationRequired; final String model; PredictionState.fromJson(Map<String,dynamic> j):current=(j['current']??0).toDouble(),after1Hour=(j['after1Hour']??0).toDouble(),after3Hours=(j['after3Hours']??0).toDouble(),after6Hours=(j['after6Hours']??0).toDouble(),irrigationRequired=j['irrigationRequired']==true,model=j['model']??''; }
