class DigitalTwinData {
 final bool online; final String zoneId,synchronizationStatus; final SensorData? sensorData; final DiseaseResult? latestDiagnosis; final String? latestImage; final DateTime? lastSensorUpdate,lastCameraCapture; final CropState? cropState; final RiskState? riskState; final PredictionState? predictionState; final Recommendation? recommendation; final ActuatorState? actuatorState;
 DigitalTwinData({required this.online,required this.zoneId,required this.synchronizationStatus,this.sensorData,this.latestDiagnosis,this.latestImage,this.lastSensorUpdate,this.lastCameraCapture,this.cropState,this.riskState,this.predictionState,this.recommendation,this.actuatorState});
 factory DigitalTwinData.fromJson(Map<String,dynamic> j)=>DigitalTwinData(online:j['online']==true,zoneId:j['zoneId']??'zone_1',synchronizationStatus:j['synchronizationStatus']??'OFFLINE',sensorData:j['sensorData'] is Map?SensorData.fromJson(Map<String,dynamic>.from(j['sensorData'])):null,latestDiagnosis:j['latestDiagnosis'] is Map?DiseaseResult.fromJson(Map<String,dynamic>.from(j['latestDiagnosis'])):null,latestImage:j['latestImage']?.toString(),lastSensorUpdate:DateTime.tryParse(j['lastSensorUpdate']?.toString()??''),lastCameraCapture:DateTime.tryParse(j['lastCameraCapture']?.toString()??''),cropState:j['cropState'] is Map?CropState.fromJson(Map<String,dynamic>.from(j['cropState'])):null,riskState:j['riskState'] is Map?RiskState.fromJson(Map<String,dynamic>.from(j['riskState'])):null,predictionState:j['predictionState'] is Map?PredictionState.fromJson(Map<String,dynamic>.from(j['predictionState'])):null,recommendation:j['recommendation'] is Map?Recommendation.fromJson(Map<String,dynamic>.from(j['recommendation'])):null,actuatorState:j['actuatorState'] is Map?ActuatorState.fromJson(Map<String,dynamic>.from(j['actuatorState'])):null);
